'use client';

import { useState } from 'react';
import { useRooms } from '@/hooks/useRooms';
import { useSession } from '@/hooks/useSession';
import { useRouter } from 'next/navigation';

export default function RoomsIndexPage() {
    const [roomName, setRoomName] = useState('');
    const [isPublic, setIsPublic] = useState(true);
    const { createRoom } = useRooms();
    const { user, session } = useSession();
    const router = useRouter();
    const [creating, setCreating] = useState(false);

    const handleCreate = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!roomName.trim() || !user) return;

        setCreating(true);
        try {
            const newRoom = await createRoom({
                name: roomName,
                creatorId: user.userId,
                isPublic,
                roomCode: !isPublic ? Math.random().toString(36).substring(7) : undefined // Simple random code
            });
            router.push(`/room/${newRoom.$id}`);
        } catch (error) {
            console.error(error);
            alert("Failed to create room");
        } finally {
            setCreating(false);
        }
    };

    if (!session) {
        // useSession hook in layout or page should handle redirect ideally, 
        // but adding here for safety
        if (typeof window !== 'undefined') router.push('/session');
        return null;
    }

    return (
        <div className="flex-1 flex items-center justify-center bg-gray-50 p-6">
            <div className="max-w-md w-full bg-white p-8 rounded-3xl border border-gray-100 shadow-sm">
                <div className="text-center mb-8">
                    <h2 className="text-2xl font-bold text-gray-900">Create a Room</h2>
                    <p className="text-gray-500 mt-2">Start a new secure channel for your team</p>
                </div>

                <form onSubmit={handleCreate} className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Room Name</label>
                        <input
                            type="text"
                            value={roomName}
                            onChange={(e) => setRoomName(e.target.value)}
                            placeholder="e.g. Project Alpha"
                            className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500"
                        />
                    </div>

                    <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-xl">
                        <input
                            type="checkbox"
                            checked={isPublic}
                            onChange={(e) => setIsPublic(e.target.checked)}
                            className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500"
                        />
                        <div className="flex-1">
                            <p className="text-sm font-medium text-gray-900">Public Room</p>
                            <p className="text-xs text-gray-500">Visible to everyone in the lobby</p>
                        </div>
                    </div>

                    <button
                        type="submit"
                        disabled={creating || !roomName.trim()}
                        className="w-full bg-blue-600 text-white font-medium py-3 rounded-xl hover:bg-blue-700 transition disabled:opacity-50"
                    >
                        {creating ? 'Creating...' : 'Create Room +'}
                    </button>
                </form>
            </div>
        </div>
    );
}
